      const wasm = await get(base + 'sql-wasm.wasm');
      if (wasm[0] !== 0x00 || wasm[1] !== 0x61) throw new Error('not wasm (got HTML)');
      const sb = { console, require, __dirname: process.cwd(), __filename: path.join(process.cwd(), '_s.js'),
        Uint8Array, Buffer, process, setTimeout, clearTimeout, WebAssembly,
        document: { getElementById: el, querySelector: s => el(s.replace(/^#/, '')), querySelectorAll: () => [], addEventListener(){} } };
      vm.createContext(sb);
      vm.runInContext((await get(base + 'sql-wasm.js')).toString('utf8'), sb);
      SQL = await sb.initSqlJs({ wasmBinary: new Uint8Array(wasm) });
      console.log('CDN OK:', base);
      break;
    } catch (e) { console.log('  跳过', base, '->', e.message); }
  }
  if (!SQL) throw new Error('所有 CDN 均失败');

  const dbPath = path.join(dir, 'holding.sqlite');
  const db = new SQL.Database(new Uint8Array(fs.readFileSync(dbPath)));
  const w = {}; vm.runInNewContext(fs.readFileSync(path.join(dir, 'config.js'), 'utf8'), { window: w, console });
  const cfg = w.PANEL_CONFIG;
  const now = new Date().toISOString();
  db.run("INSERT OR REPLACE INTO setting(k,v) VALUES(?,?)", ['cfg', JSON.stringify(cfg)]);
  db.run("INSERT OR REPLACE INTO setting(k,v) VALUES(?,?)", ['cfgSyncedAt', now]);
  db.run("INSERT OR REPLACE INTO setting(k,v) VALUES(?,?)", ['cfgSource', 'sync']);
  fs.writeFileSync(dbPath, Buffer.from(db.export()));
  console.log('SYNCED ' + cfg.targets.length + ' targets -> holding.sqlite');
  const t = cfg.targets.find(x => x.code === '000999');
  console.log('000999 yld=' + t.yld + '%  yldFy=' + t.yldFy + '%  targetBuy=' + t.targetBuy + '元');
})().catch(e => { console.error('ERR', e.message); process.exit(1); });
